import{_ as s,c as r,o as a,ah as i,j as e,a as n}from"./chunks/framework.CAZQ2vdu.js";const l="/Qonnectra-docs/pr-17/images/manual/teil-a/schema.jpg",d="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_panel.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_search.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_lock.jpg",c="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_cable_type.jpg",u="/Qonnectra-docs/pr-17/videos/schema_cable_connect.webm",m="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_cable_properties.jpg",b="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_cable_actions.jpg",g="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_edit_mode.jpg",p="/Qonnectra-docs/pr-17/videos/schema_cable_path.webm",f="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_handles.jpg",k="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_micropipe_trenches.jpg",z="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_micropipe_microducts.jpg",S="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_fiber_status.jpg",K="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_slot_config.jpg",v="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_structure.jpg",_="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_ports.jpg",w="/Qonnectra-docs/pr-17/videos/schema_splice_drag.webm",A="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_port_merge.jpg",N="/Qonnectra-docs/pr-17/images/manual/teil-a/schema_subnet.jpg",T=JSON.parse('{"title":"14. Netzschema","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/14-netzschema.md","filePath":"manual/teil-a-anwenderhandbuch/14-netzschema.md"}'),F={name:"manual/teil-a-anwenderhandbuch/14-netzschema.md"};function P(B,t,D,E,M,Z){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_14-netzschema" tabindex="-1">14. Netzschema <a class="header-anchor" href="#_14-netzschema" aria-label="Permalink to &quot;14. Netzschema&quot;">​</a></h1><p>Das <strong>Netzschema</strong> ist die Ansicht, in der das Kabelnetz entsteht: Hier legen Sie Kabel zwischen Netzknoten an, verknüpfen sie mit Mikrorohren, spleißen Fasern auf Ports und dokumentieren den inneren Aufbau eines Netzknotens. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Kabel“ durch Klicken auf den Menüpunkt „Netzschema“.</p><p><img src="'+l+'" alt="Screenshot des Netzschemas mit Netzknoten und Kabeln und dem Bereich „Eigenschaften“ oben links" data-zoomable="true"></p><p>Alles, was Kapitel <a href="./02-grundbegriffe-und-datenmodell.html">Grundbegriffe und Datenmodell</a> über Kabel, Bündel, Fasern und Spleiße sagt, entsteht in dieser Ansicht. Die Karte und die Rohrverwaltung zeigen dieselben Objekte nur zum Lesen.</p><h2 id="_14-1-aufbau-des-schemas-netzknoten-und-kabel" tabindex="-1">14.1 Aufbau des Schemas: Netzknoten und Kabel <a class="header-anchor" href="#_14-1-aufbau-des-schemas-netzknoten-und-kabel" aria-label="Permalink to &quot;14.1 Aufbau des Schemas: Netzknoten und Kabel&quot;">​</a></h2><p>Den größten Teil der Ansicht nimmt die <strong>Zeichenfläche</strong> ein. Sie ist ein Diagramm und keine Karte: Ein Netzknoten steht als Kasten mit seinem Namen darin, ein Kabel als Linie zwischen zwei Kästen, beschriftet mit dem Kabelnamen. An jeder Seite eines Kastens sitzt ein grüner Punkt – ein <strong>Fangpunkt</strong>, an dem ein Kabel andockt.</p><p>Wo ein Netzknoten auf der Zeichenfläche liegt, hat mit seiner Lage im Gelände zunächst durchaus zu tun: Qonnectra rechnet die Position beim ersten Öffnen aus den Koordinaten der Karte, siehe Abschnitt <a href="#_14-11-kartenkoordinaten-mit-dem-schema-synchronisieren">Kartenkoordinaten mit dem Schema synchronisieren</a>. Danach sind beide Positionen voneinander unabhängig.</p><p>Die Farbe eines Kabels ist keine Eigenschaft des Kabels, sondern eine Anzeigeoption: In der Voreinstellung nimmt die Linie die Farbe des Mikrorohrs mit der niedrigsten Nummer an, mit dem das Kabel verknüpft ist. Umstellen können Sie das unter „Kabelfarbe“ in den Einstellungen, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>.</p><p>Oben links liegt der Bereich „Eigenschaften“. Er enthält die beiden Felder für ein neues Kabel („Name“ und „Kabeltyp auswählen“), die „Anzeigeoptionen“ (siehe Abschnitt <a href="#_14-10-anzeigeoptionen-einrasten-kabelrichtungs-animation">Anzeigeoptionen</a>) und das Suchfeld. Ein Klick auf die Überschrift klappt den ganzen Bereich zu, ein Klick auf „Anzeigeoptionen“ nur diesen Teil.</p><p><img src="'+d+'" alt="Screenshot des Netzschemas mit Hervorhebung des Bereichs „Eigenschaften“ oben links" data-zoomable="true"></p><p>Unten links sitzen die Schaltflächen der Zeichenfläche, siehe Abschnitt <a href="#_14-2-netzknoten-verschieben-verbinden-und-loschen">Netzknoten verschieben, verbinden und löschen</a>. Ein Klick auf einen Netzknoten oder auf die Beschriftung eines Kabels öffnet rechts die Info-Box, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-die-info-box-mit-ihren-reitern">Die Info-Box</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Schema zeigt nicht alle Netzknoten des Projekts, sondern nur die Netzknotentypen, die Ihre Administration in den <strong>Netzschema-Einstellungen</strong> dafür vorgesehen hat, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>. Üblicherweise bleiben die Hausanschlüsse ausgeblendet – es sind zu viele für ein lesbares Diagramm; Sie erreichen sie über das Subnetz ihres Verteilers, siehe Abschnitt <a href="#_14-9-subnetz-eines-netzknotens">Subnetz eines Netzknotens</a>.</p><p>Fehlen die Einstellungen ganz, meldet Qonnectra beim Öffnen „Die Netzschema-Einstellungen sind für dieses Projekt nicht konfiguriert. Bitte konfigurieren Sie diese im Admin-Bereich.“ und zeigt jeden Netzknoten – bei vielen Hausanschlüssen wird das Diagramm damit unübersichtlich.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Netzknoten ohne Geometrie bekommt keine berechnete Position und landet im Nullpunkt der Zeichenfläche, weit außerhalb der übrigen Netzknoten. Wo ein Netzknoten liegt, erfassen Sie in QGIS, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>.</p></div><h3 id="_14-1-1-objekte-im-schema-suchen" tabindex="-1">14.1.1 Objekte im Schema suchen <a class="header-anchor" href="#_14-1-1-objekte-im-schema-suchen" aria-label="Permalink to &quot;14.1.1 Objekte im Schema suchen&quot;">​</a></h3><p>Das Suchfeld unter den Anzeigeoptionen durchsucht die Namen der Netzknoten <strong>und</strong> der Kabel des Diagramms. Zu jedem Treffer steht rechts, um welche Art Objekt es sich handelt.</p><p><img src="'+o+'" alt="Screenshot des Netzschemas mit Hervorhebung des Suchfeldes und der Trefferliste mit Netzknoten und Kabeln" data-zoomable="true"></p><p>Ein Klick auf einen Treffer rückt ihn in die Mitte der Zeichenfläche und hebt ihn hervor. Die Info-Box öffnet er nicht – dafür klicken Sie danach auf den Netzknoten oder die Beschriftung.</p><h2 id="_14-2-netzknoten-verschieben-verbinden-und-loschen" tabindex="-1">14.2 Netzknoten verschieben, verbinden und löschen <a class="header-anchor" href="#_14-2-netzknoten-verschieben-verbinden-und-loschen" aria-label="Permalink to &quot;14.2 Netzknoten verschieben, verbinden und löschen&quot;">​</a></h2><p>Beim Öffnen ist die Zeichenfläche <strong>gesperrt</strong>. Unten links liegen vier Schaltflächen: hineinzoomen, herauszoomen, alles einpassen und das Schloss. Die Hinweise der ersten drei sind englisch beschriftet („Zoom In“, „Zoom Out“, „Fit View“), der des Schlosses deutsch („Zeichenfläche entsperren“).</p><p><img src="'+h+'" alt="Screenshot des Netzschemas mit Hervorhebung der Schaltflächen zum Zoomen und Sperren unten links" data-zoomable="true"></p><p>Ein Klick auf das Schloss hebt die Sperre auf. Erst danach lassen sich Netzknoten verschieben, Kabel anlegen und Kabel bearbeiten. Den Ausschnitt verschieben, zoomen und Info-Boxen öffnen können Sie in beiden Zuständen.</p><p><strong>Netzknoten verschieben</strong></p><p>Ziehen Sie einen Kasten mit gedrückter linker Maustaste an eine andere Stelle. Er rastet auf einem Raster von 120 Pixeln ein, und mit dem Loslassen ist die neue Position gespeichert; Qonnectra meldet „Position erfolgreich aktualisiert“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Verschoben wird ausschließlich die Position im Diagramm. Die Karte bleibt unberührt – umgekehrt ändert eine Verschiebung in QGIS die Position im Schema nicht mehr, sobald der Netzknoten dort einmal einen Platz hat.</p></div><p><strong>Kabel anlegen</strong></p><p>Ein neues Kabel entsteht in zwei Schritten:</p><ol><li>Tragen Sie im Bereich „Eigenschaften“ einen „Namen“ ein und wählen Sie unter „Kabeltyp auswählen“ den Kabeltyp.</li><li>Ziehen Sie mit gedrückter linker Maustaste von einem grünen Fangpunkt des einen Netzknotens auf einen Fangpunkt des anderen.</li></ol><p><img src="'+c+'" alt="Screenshot des Netzschemas mit Hervorhebung des Bereichs „Eigenschaften“ und der geöffneten Liste der Kabeltypen" data-zoomable="true"></p>',28),e("p",null,[e("video",{src:u,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/schema_cable_connect.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<p>Mit dem Loslassen ist das Kabel angelegt, Qonnectra meldet „Kabel erfolgreich erstellt“. Aus dem Kabeltyp entstehen dabei sofort alle Fasern und Bündel, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-2-kabel-bundel-faser-und-spleiß">Kabel, Bündel, Faser und Spleiß</a>. Anschließend versucht Qonnectra, das Kabel selbständig mit einem Mikrorohr zu verknüpfen, siehe Abschnitt <a href="#_14-5-kabel-mit-mikrorohren-verknupfen">Kabel mit Mikrorohren verknüpfen</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Kabeltyp ist Pflicht: Ohne ihn meldet Qonnectra „Kein Kabeltyp ausgewählt“, und es entsteht kein Kabel. Nachträglich lässt er sich nicht mehr ändern, siehe Abschnitt <a href="#_14-3-kabeleigenschaften-kabeltyp-und-kabellange-neu-berechnen">Kabeleigenschaften</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der eingetragene Name ist nicht der endgültige: Qonnectra hängt zehn zufällige Zeichen an („St-V05-144-Fs-hK3pQ2Lm9x“), damit der Name in der gesamten Installation eindeutig ist – bei Kabeln gilt das strenger als bei Rohren und Netzknoten, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-2-kabel-bundel-faser-und-spleiß">Kabel, Bündel, Faser und Spleiß</a>. Bleibt das Feld leer, besteht der Name nur aus diesen zehn Zeichen. Umbenennen können Sie das Kabel danach im Reiter „Eigenschaften“.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Welche Seite Anfang und welche Ende des Kabels ist, ergibt sich aus der Ziehrichtung – allerdings andersherum, als man erwartet: Der Netzknoten, auf dem Sie loslassen, wird zum Anfang. Umstellen können Sie das im Reiter „Fangpunkte“, siehe Abschnitt <a href="#_14-4-bearbeitungsmodus-kabelverlauf-beschriftung-und-fangpunkte">Bearbeitungsmodus</a>.</p></div><p><strong>Netzknoten löschen</strong></p><p>Netzknoten legen Sie in der Weboberfläche nicht an; sie kommen aus QGIS oder aus einem Import, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>. Löschen können Sie sie hier: im Reiter „Eigenschaften“ der Info-Box mit „Netzknoten löschen“.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Mit dem Netzknoten verschwindet auch sein innerer Aufbau. Die Rückfrage nennt vorher, was betroffen ist („… 2 Komponenten werden gelöscht.“).</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Solange Kabel am Netzknoten hängen, ist „Netzknoten löschen“ ausgegraut; ein Zeigen mit der Maus nennt den Grund („Dieser Netzknoten kann nicht gelöscht werden, da Kabel verbunden sind. Bitte entferne zuerst die Kabel.“). Dasselbe gilt, wenn ein <strong>untergeordneter</strong> Netzknoten Kabel hat – die sehen Sie erst im Subnetz, siehe Abschnitt <a href="#_14-9-subnetz-eines-netzknotens">Subnetz eines Netzknotens</a>.</p></div><h2 id="_14-3-kabeleigenschaften-kabeltyp-und-kabellange-neu-berechnen" tabindex="-1">14.3 Kabeleigenschaften, Kabeltyp und Kabellänge neu berechnen <a class="header-anchor" href="#_14-3-kabeleigenschaften-kabeltyp-und-kabellange-neu-berechnen" aria-label="Permalink to &quot;14.3 Kabeleigenschaften, Kabeltyp und Kabellänge neu berechnen&quot;">​</a></h2><p>Ein Klick auf die Beschriftung eines Kabels öffnet die Info-Box mit den Reitern „Eigenschaften“, „Status“, „Fangpunkte“, „Aktionen“ und „Anhänge“. Das ausgewählte Kabel ist auf der Zeichenfläche dicker gezeichnet.</p><p>Der Reiter „Eigenschaften“ enthält den Namen, die Stammdaten (Status, Netzebene, Eigentümer, Baufirma, Hersteller, Datum, Kennzeichen) und darunter die drei Reserven „Reserve am Anfang“, „Reserve am Ende“ und „Reserve auf der Strecke“ sowie „Länge“ und „Gesamtlänge“. „Speichern“ übernimmt die Änderungen.</p><p><img src="'+m+'" alt="Screenshot des Netzschemas mit Hervorhebung der Info-Box eines Kabels im Reiter „Eigenschaften“" data-zoomable="true"></p><p>Drei Felder verhalten sich anders als die übrigen:</p><ul><li><strong>„Kabeltyp“</strong> ist ausgegraut und bleibt <strong>leer</strong>, auch wenn das Kabel einen Kabeltyp hat. Er steht damit fest und lässt sich nicht mehr ändern; nachlesen können Sie ihn in der Kabelübersicht einer Trasse, siehe Abschnitt <a href="./05-karte.html#_5-4-rohrubersicht-und-kabelubersicht-einer-trasse">Rohrübersicht und Kabelübersicht einer Trasse</a>.</li><li><strong>„Verbundene Leerrohre“</strong> listet die Rohre auf, in deren Mikrorohren das Kabel liegt. Das Feld ist nur zu lesen und ergibt sich aus Abschnitt <a href="#_14-5-kabel-mit-mikrorohren-verknupfen">Kabel mit Mikrorohren verknüpfen</a>.</li><li><strong>„Länge“</strong> und <strong>„Gesamtlänge“</strong> sind berechnet und ebenfalls nur zu lesen, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-2-kabel-bundel-faser-und-spleiß">Kabel, Bündel, Faser und Spleiß</a>.</li></ul><p>Der Reiter „Aktionen“ hält zwei Schaltflächen bereit: „Mit Mikrorohr verbinden“ (siehe den nächsten Abschnitt) und „Kabellänge neu berechnen“.</p><p><img src="'+b+'" alt="Screenshot des Netzschemas mit Hervorhebung der Info-Box eines Kabels im Reiter „Aktionen“" data-zoomable="true"></p><p>„Kabellänge neu berechnen“ ermittelt die Länge erneut aus den Trassen, durch die das Kabel läuft, und meldet „Kabellänge neu berechnet“. Nötig ist das nach jeder Änderung an den Mikrorohr-Verknüpfungen und nach jeder Änderung an den Trassenlängen – von selbst rechnet Qonnectra nicht nach.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ist das Kabel mit keinem Mikrorohr verknüpft, ergibt die Berechnung 0 m. Findet Qonnectra keinen durchgehenden Weg zwischen Anfangs- und Endknoten, summiert es stattdessen die Längen aller Trassen, in denen das Kabel liegt – der Wert fällt dann zu groß aus.</p></div><p>„Kabel löschen“ im Reiter „Eigenschaften“ entfernt das Kabel.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Mit dem Kabel gehen seine Fasern und alle Spleiße verloren, die auf diesen Fasern liegen. Die Rückfrage nennt vorher deren Anzahl.</p></div><h2 id="_14-4-bearbeitungsmodus-kabelverlauf-beschriftung-und-fangpunkte" tabindex="-1">14.4 Bearbeitungsmodus: Kabelverlauf, Beschriftung und Fangpunkte <a class="header-anchor" href="#_14-4-bearbeitungsmodus-kabelverlauf-beschriftung-und-fangpunkte" aria-label="Permalink to &quot;14.4 Bearbeitungsmodus: Kabelverlauf, Beschriftung und Fangpunkte&quot;">​</a></h2><p>Der Verlauf einer Kabellinie und die Lage ihrer Beschriftung lassen sich ändern – aber nur im <strong>Bearbeitungsmodus</strong>, und der gilt immer für genau ein Kabel. Zwei Voraussetzungen: Die Zeichenfläche muss entsperrt sein, und das Kabel muss der Bearbeitungsgegenstand sein.</p><p>So schalten Sie den Modus ein:</p><ol><li>Entsperren Sie die Zeichenfläche, siehe Abschnitt <a href="#_14-2-netzknoten-verschieben-verbinden-und-loschen">Netzknoten verschieben, verbinden und löschen</a>.</li><li>Klicken Sie mit der rechten Maustaste auf die Beschriftung des Kabels und dann auf „Kabel bearbeiten“.</li></ol><p><img src="'+g+'" alt="Screenshot des Netzschemas mit Hervorhebung der Kabelbeschriftung und des Kontextmenüs mit dem Eintrag „Kabel bearbeiten“" data-zoomable="true"></p><p>Am oberen rechten Rand der Zeichenfläche steht danach „Bearbeite:“ mit dem Namen des Kabels. Das Kreuz daneben beendet den Modus, ebenso die Taste Esc oder der Eintrag „Kabelbearbeitung beenden“ im Kontextmenü. Statt über das Menü kommen Sie mit Alt + Klick auf eine Beschriftung direkt in den Modus – auch aus dem Modus eines anderen Kabels heraus.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Klick auf die Beschriftung ohne Alt öffnet immer die Info-Box, in jedem Zustand. Die Bearbeitung liegt also nicht im Weg, wenn Sie nur die Eigenschaften lesen wollen.</p></div><h3 id="_14-4-1-verlauf-eines-kabels-andern" tabindex="-1">14.4.1 Verlauf eines Kabels ändern <a class="header-anchor" href="#_14-4-1-verlauf-eines-kabels-andern" aria-label="Permalink to &quot;14.4.1 Verlauf eines Kabels ändern&quot;">​</a></h3><p>Im Bearbeitungsmodus zeichnet Qonnectra die Linie dicker und mit einem Schein. Ein Klick auf die Linie setzt an dieser Stelle einen <strong>Scheitelpunkt</strong> – einen Knick, mit dem Sie das Kabel um andere Objekte herumführen.</p>',29),e("p",null,[e("video",{src:p,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/schema_cable_path.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<p>Die Punkte sind als blasse Kreise auf der Linie gezeichnet und werden deutlich, sobald der Mauszeiger die Linie berührt. Ziehen verschiebt einen Punkt, Shift + Klick löscht ihn. Jede Änderung ist sofort gespeichert; Qonnectra meldet „Kabelgeometrie erfolgreich aktualisiert“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Solange „Einrasten“ eingeschaltet ist, springen die Punkte auf ein Raster von 20 Pixeln, siehe Abschnitt <a href="#_14-10-anzeigeoptionen-einrasten-kabelrichtungs-animation">Anzeigeoptionen</a>. Der Verlauf ist reine Darstellung – für den Weg des Kabels im Gelände sind die Mikrorohre zuständig.</p></div><h3 id="_14-4-2-beschriftung-verschieben-und-zurucksetzen" tabindex="-1">14.4.2 Beschriftung verschieben und zurücksetzen <a class="header-anchor" href="#_14-4-2-beschriftung-verschieben-und-zurucksetzen" aria-label="Permalink to &quot;14.4.2 Beschriftung verschieben und zurücksetzen&quot;">​</a></h3><p>Wo eine Beschriftung liegt, ist am Kabel gespeichert. Ist dort keine Position hinterlegt, setzt Qonnectra sie in die Mitte der Linie; andernfalls steht sie genau an der gespeicherten Stelle.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Bei importierten Kabeln stammt diese Position aus dem Herkunftssystem. Zeichnet Qonnectra die Linie anders – etwa mit einem rechten Winkel um einen Netzknoten herum –, liegt die Beschriftung dann neben ihrem Kabel. Von selbst rückt sie nicht nach; ziehen Sie sie an die Linie.</p></div><p>Verschieben können Sie sie so: Halten Sie die linke Maustaste eine halbe Sekunde auf der Beschriftung gedrückt – ein Ring am Mauszeiger füllt sich –, danach folgt sie der Maus. Mit dem Loslassen ist die neue Position gespeichert; Qonnectra meldet „Kabelbeschriftung erfolgreich gespeichert“. Shift + Klick setzt die Position zurück, sodass die Beschriftung wieder in der Mitte der Linie liegt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beides wirkt nur im Bearbeitungsmodus. Außerhalb öffnet auch ein langes Drücken nur die Info-Box – die Beschriftung wirkt dann festgeklebt.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Zurücksetzen löscht die gespeicherte Position und setzt damit die Zugriffsstufe „Vollzugriff“ voraus; die Berechtigung zum Bearbeiten genügt dafür nicht. Fehlt sie, springt die Beschriftung kurz in die Mitte, Qonnectra meldet „Fehler beim Speichern der Kabelbeschriftung“, und sie liegt danach wieder an ihrer alten Stelle. Verschieben Sie sie in diesem Fall von Hand, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</p></div><h3 id="_14-4-3-reiter-„fangpunkte" tabindex="-1">14.4.3 Reiter „Fangpunkte“ <a class="header-anchor" href="#_14-4-3-reiter-„fangpunkte" aria-label="Permalink to &quot;14.4.3 Reiter „Fangpunkte“&quot;">​</a></h3><p>Der Reiter „Fangpunkte“ der Info-Box zeigt, an welchen Netzknoten das Kabel hängt und an welcher Seite des Kastens: je Ende die Überschrift mit dem Netzknotennamen, darunter das Feld „Netzknoten ändern“ und die vier Möglichkeiten „Oben“, „Rechts“, „Unten“ und „Links“. „Speichern“ übernimmt die Auswahl.</p><p><img src="'+f+'" alt="Screenshot des Netzschemas mit Hervorhebung der Info-Box eines Kabels im Reiter „Fangpunkte“" data-zoomable="true"></p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>„Netzknoten ändern“ hängt das Kabelende an einen anderen Netzknoten um. Liegen am alten Netzknoten Spleiße auf den Fasern dieses Kabels, werden sie dabei gelöscht; die Rückfrage nennt ihre Anzahl („Durch das Ändern der Netzknotenverbindung werden Faserverbindungen gelöscht. 24 Faserverbindungen.“). Mit „Abbrechen“ bleibt alles, wie es war.</p></div><h2 id="_14-5-kabel-mit-mikrorohren-verknupfen" tabindex="-1">14.5 Kabel mit Mikrorohren verknüpfen <a class="header-anchor" href="#_14-5-kabel-mit-mikrorohren-verknupfen" aria-label="Permalink to &quot;14.5 Kabel mit Mikrorohren verknüpfen&quot;">​</a></h2><p>Ein Kabel hat keine eigene Geometrie: Wo es verläuft, ergibt sich aus dem Mikrorohr, in dem es liegt, und aus den Trassen dieses Rohrs. Diese Verknüpfung stellen Sie hier her – sie ist die Voraussetzung für die Kabellänge (Abschnitt <a href="#_14-3-kabeleigenschaften-kabeltyp-und-kabellange-neu-berechnen">Kabeleigenschaften</a>), für den Faserweg (Kapitel <a href="./15-faserweg.html">Faserweg</a>) und für die Störungsanalyse (Kapitel <a href="./06-stoerungsanalyse.html">Störungsanalyse</a>).</p><p><strong>Automatisch beim Anlegen</strong></p><p>Direkt nach dem Anlegen eines Kabels sucht Qonnectra an beiden Enden nach einem passenden Mikrorohr: nach einem, das einem Netzknoten mit derselben Adresse zugeordnet ist – also einem, an dem Sie einen Hausanschluss dokumentiert haben, siehe Kapitel <a href="./13-mikrorohre.html">Mikrorohre</a>. Mikrorohre mit einem Status bleiben außen vor. Findet Qonnectra genau eines, verknüpft es das Kabel damit und meldet „Mikrorohr St-V02-01 #3 blau wurde automatisch verknüpft“.</p><p>Hat der Endknoten keine Adresse oder findet sich kein Mikrorohr, geschieht nichts – ohne Meldung. Kommen mehrere Mikrorohre infrage, fragt das Fenster „Mikrorohr auswählen“ nach: Es nennt die Adresse und listet die Kandidaten mit Rohrnamen, Nummer und Farbe auf; zu Mikrorohren, in denen schon ein Kabel liegt, steht dessen Name darunter. „Abbrechen“ überspringt das Ende – verknüpfen können Sie es später von Hand.</p><p><strong>Von Hand</strong></p><p>Im Reiter „Aktionen“ öffnet „Mit Mikrorohr verbinden“ das Fenster „Kabel-Mikrorohr Verknüpfung“. Es ist zweigeteilt: links eine Karte des Projekts, die sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben verhält, rechts die Auswahl in zwei Schritten.</p><p>Schritt 1 („Gräben“) beginnt mit dem Hinweis „Wählen Sie Gräben auf der Karte aus“. Klicken Sie in der Karte auf die Trassen, durch die das Kabel läuft; ein erneuter Klick nimmt eine Trasse wieder aus der Auswahl, mit Shift und gedrückter linker Maustaste ziehen Sie einen Rahmen um mehrere. Rechts steht darauf, wie viele Gräben ausgewählt sind, und darunter die Leerrohre, die in ihnen liegen. Rohre, in denen bereits ein Kabel liegt, sind mit „Verknüpft“ gekennzeichnet.</p><p><img src="'+k+'" alt="Screenshot des Fensters „Kabel-Mikrorohr Verknüpfung“ mit der Karte links und der Liste der Leerrohre einer ausgewählten Trasse rechts" class="big" data-zoomable="true"></p><p>Kreuzen Sie die Rohre an, in denen das Kabel liegt, und klicken Sie auf „Weiter“. Schritt 2 („Mikrorohre“) zeigt die Mikrorohre dieser Rohre in einer Tabelle mit „Farbe“, „Verfügbar“ und „Status“. Wählen Sie eines aus und speichern Sie.</p><p><img src="'+z+'" alt="Screenshot des Fensters „Kabel-Mikrorohr Verknüpfung“ mit der Tabelle der Mikrorohre im zweiten Schritt" class="big" data-zoomable="true"></p><p>Der Umschalter „Route anzeigen“ oben rechts zeichnet den bisherigen Weg des Kabels in die Karte – hilfreich, um zu sehen, wo die nächste Trasse anschließen muss. „Auswahl löschen“ hebt die Trassenauswahl auf, die Ziffern „1“ und „2“ über der Auswahl wechseln zwischen den Schritten.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Haben Sie mehrere Rohre angekreuzt, muss dasselbe Mikrorohr in allen vorkommen. Fehlt es in einem, steht in der Zeile „Nicht verfügbar in: …“, und die Auswahl ist gesperrt.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Verknüpfung ändert die Kabellänge nicht von selbst. Rechnen Sie sie anschließend mit „Kabellänge neu berechnen“ nach.</p></div><h2 id="_14-6-fasern-und-bundel-eines-kabels" tabindex="-1">14.6 Fasern und Bündel eines Kabels <a class="header-anchor" href="#_14-6-fasern-und-bundel-eines-kabels" aria-label="Permalink to &quot;14.6 Fasern und Bündel eines Kabels&quot;">​</a></h2><p>Der Reiter „Status“ der Info-Box listet die Bündel des Kabels auf; ein Klick auf ein Bündel klappt seine Fasern mit „#“, „Farbe“ und „Status“ auf. Wie diese Nummern und Farben zustande kommen, steht in Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-2-kabel-bundel-faser-und-spleiß">Kabel, Bündel, Faser und Spleiß</a>.</p><p>Diese Ansicht ist die einzige Stelle, an der Sie den <strong>Status einer Faser</strong> ändern können: Wählen Sie in der Zeile der Faser einen Status aus der Liste. Sie enthält „Intakt“ und die Faserstatus Ihrer Installation – meist nur den Begriff „Defekt“.</p><p><img src="'+S+'" alt="Screenshot des Netzschemas mit Hervorhebung der Info-Box eines Kabels im Reiter „Status“ und der geöffneten Statusliste einer Faser" data-zoomable="true"></p><p>Die Auswahl ist sofort gespeichert. Eine defekte Faser ist danach überall durchgestrichen dargestellt, und am Bündel steht, wie viele seiner Fasern defekt sind – auch in der Kabelübersicht der Karte, siehe Abschnitt <a href="./05-karte.html#_5-4-rohrubersicht-und-kabelubersicht-einer-trasse">Rohrübersicht und Kabelübersicht einer Trasse</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Qonnectra bestätigt die Änderung mit „Mikrorohr-Status aktualisiert“. Gemeint ist der Status der Faser; die Meldung ist an dieser Stelle falsch beschriftet.</p></div><h2 id="_14-7-netzknoten-offnen-slot-konfiguration-struktur-container" tabindex="-1">14.7 Netzknoten öffnen: Slot-Konfiguration, Struktur, Container <a class="header-anchor" href="#_14-7-netzknoten-offnen-slot-konfiguration-struktur-container" aria-label="Permalink to &quot;14.7 Netzknoten öffnen: Slot-Konfiguration, Struktur, Container&quot;">​</a></h2><p>Der Reiter „Aktionen“ eines Netzknotens führt zu seinem inneren Aufbau: „Slots konfigurieren“ öffnet das Fenster „Netzknoten-Konfiguration“, „Struktur konfigurieren“ das Fenster „Netzknotenstruktur“. Beide Fenster kennen Sie aus der Karte, dort sind sie reine Anzeigen – wie sie aufgebaut sind, steht in Abschnitt <a href="./05-karte.html#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen">Netzknoten: Slot-Konfiguration und Struktur öffnen</a>. Im Netzschema sind sie bearbeitbar.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beide Fenster öffnen mittig und gleich groß übereinander, und „Netzknotenstruktur“ liegt immer oben. Ziehen Sie das obere Fenster an seiner Titelzeile beiseite, wenn Sie beide gleichzeitig brauchen – Abschnitt <a href="./05-karte.html#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen">Netzknoten: Slot-Konfiguration und Struktur öffnen</a> beschreibt das Verhalten im Einzelnen.</p></div><p><strong>Einbauplätze und Container anlegen</strong></p><p>„Hinzufügen“ legt eine neue Slot-Konfiguration an: „Seite“ (ein kurzer Name wie „A“ oder „Muffe“) und „Gesamtslots“, also die Anzahl der Einbauplätze. „Container hinzufügen“ legt einen Container an – „Container-Typ“ ist Pflicht, „Name (optional)“ nicht.</p><p><img src="'+K+'" alt="Screenshot des Fensters „Netzknoten-Konfiguration“ mit dem Container „RACK-A1“ und der darin liegenden Slot-Konfiguration" class="big" data-zoomable="true"></p><p>Jede Zeile trägt rechts ihre Schaltflächen: das Auge zeigt die Struktur dieser Seite, der Stift öffnet die Konfiguration zum Bearbeiten, der Papierkorb löscht sie. Das Auge schaltet dabei das Fenster „Netzknotenstruktur“ auf diese Seite um – ist es schon offen, holt es das Fenster aber nicht nach vorn, siehe Abschnitt <a href="./05-karte.html#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen">Netzknoten: Slot-Konfiguration und Struktur öffnen</a>. Am Griff links ziehen Sie eine Slot-Konfiguration in einen Container oder aus ihm heraus; Container lassen sich ineinander schieben. Das Download-Symbol oben rechts speichert den Aufbau als Excel-Datei, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Container-Typen sind Stammdaten der Installation und lassen sich nur im Administrationsbereich anlegen, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>. Gibt es keinen einzigen, fehlt die Schaltfläche „Container hinzufügen“ ganz.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Der Papierkorb an einer Slot-Konfiguration löscht mit ihr die eingebauten Komponenten und deren Spleiße. Die Rückfrage nennt vorher deren Anzahl.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Jedes Löschen in diesem Fenster – Slot-Konfiguration wie Container – setzt die Zugriffsstufe „Vollzugriff“ voraus; die Berechtigung zum Bearbeiten genügt dafür nicht. Fehlt sie, erscheint eine Fehlermeldung, und der Eintrag bleibt stehen. Wenden Sie sich in diesem Fall an Ihre Administration, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</p></div><p><strong>Komponenten einbauen</strong></p><p>Das Fenster „Netzknotenstruktur“ hat im Netzschema drei Spalten: links die Leiste „Komponententypen“, in der Mitte das Slot-Grid, rechts die Leiste „Kabel“.</p><p><img src="'+v+'" alt="Screenshot des Fensters „Netzknotenstruktur“ mit der Leiste „Komponententypen“ links, dem Slot-Grid in der Mitte und der Kabelleiste rechts" class="big" data-zoomable="true"></p><p>Jeder Eintrag der Leiste „Komponententypen“ nennt den Typ und die Zahl der Slots, die er belegt, dazu ein Zählfeld mit „−“ und „+“. Ziehen Sie den Eintrag in eine freie Zeile des Slot-Grids: Ein grüner Rahmen zeigt, dass die Komponente dort hineinpasst, ein roter, dass die Slots schon belegt sind. Steht im Zählfeld eine höhere Zahl, baut Qonnectra mehrere Komponenten desselben Typs hintereinander ein.</p><p>Eine eingebaute Komponente ziehen Sie am Griff auf eine andere Stelle des Grids; der Papierkorb an ihrem rechten Rand entfernt sie.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Passt die Komponente nicht mehr in die restlichen Slots, meldet Qonnectra „Nicht genug Slots verfügbar“, bei belegten Slots „Slots sind bereits belegt“ – eingebaut wird dann nichts.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Der Papierkorb an einer Komponente löscht auch die Spleiße, die auf ihren Ports liegen. Die Rückfrage nennt deren Anzahl.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Auch hier setzt das Löschen die Zugriffsstufe „Vollzugriff“ voraus. Fehlt sie, meldet Qonnectra „Fehler beim Löschen der Struktur“, und die Komponente bleibt eingebaut.</p></div><h2 id="_14-8-spleiße-und-ports" tabindex="-1">14.8 Spleiße und Ports <a class="header-anchor" href="#_14-8-spleiße-und-ports" aria-label="Permalink to &quot;14.8 Spleiße und Ports&quot;">​</a></h2><p>Ein Klick auf eine eingebaute Komponente im Slot-Grid öffnet ihre Ports mit den Spalten „Port“, „Faser A“ und „Faser B“ – die beiden Seiten, zwischen denen ein Port die Fasern verbindet. „Zurück“ führt wieder in das Grid. Eine Komponente mit vielen Ports füllt mehr, als das Fenster zeigt: Maximieren Sie es über die Titelzeile, siehe Abschnitt <a href="./05-karte.html#_5-5-grabenprofil-einer-trasse">Grabenprofil einer Trasse</a>.</p><p><img src="'+_+'" alt="Screenshot des maximierten Fensters „Netzknotenstruktur“ mit der Tabelle der Ports einer Komponente: auf jedem Port eine Faser auf Seite A und eine auf Seite B" class="big" data-zoomable="true"></p><p><strong>Fasern auflegen</strong></p><p>Die Leiste „Kabel“ am rechten Rand führt alle Kabel des Netzknotens auf. Klappen Sie ein Kabel und darin ein Bündel auf und ziehen Sie eine Faser in die Zelle „Faser A“ oder „Faser B“ eines Ports – damit ist der Spleiß gesetzt, und Qonnectra meldet „Faser erfolgreich verbunden“.</p>',55),e("p",null,[e("video",{src:w,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/schema_splice_drag.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<p>Sie können auch größere Einheiten ziehen:</p><ul><li>Ein <strong>Bündel</strong> füllt die Ports ab der Zelle, in der Sie loslassen, mit seinen Fasern der Reihe nach – bis zum ersten Port, auf dem schon eine Faser liegt. Qonnectra meldet dann, wie viele Fasern verbunden wurden („24 Fasern verbunden“ oder „18 von 24 Fasern verbunden“).</li><li>Ein <strong>Kabel</strong> füllt auf dieselbe Weise weiter und läuft dabei in die folgenden Komponenten der Seite über.</li><li>Eine <strong>Wohneinheit</strong> aus dem Abschnitt „Adressen“ der Leiste belegt einen Port genauso wie eine Faser. So dokumentieren Sie, welche Wohneinheit an welchem Port hängt – der Faserweg zeigt sie später als Ziel, siehe Abschnitt <a href="./15-faserweg.html#_15-5-betroffene-adressen-und-wohneinheiten">Betroffene Adressen und Wohneinheiten</a>.</li></ul><p>Fasern, die schon auf einem Port liegen, sind in der Leiste grün hinterlegt; ein vollständig aufgelegtes Bündel ebenso. Innerhalb der Tabelle ziehen Sie eine Faser von einer Zelle in eine andere und verschieben damit den Spleiß.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine Zelle nimmt immer nur eine Faser auf. Lassen Sie eine Faser auf einer Zelle los, die schon belegt ist, <strong>ersetzt</strong> sie die bisherige – ohne Rückfrage, und ohne dass die alte Faser auf einen anderen Port ausweicht. Bei zusammengeführten Ports gilt das für die ganze Gruppe.</p></div><p>Jede belegte Zelle trägt beim Zeigen mit der Maus drei Schaltflächen: „Folgen“ öffnet den Faserweg dieser Faser (siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>) und zeigt anschließend in der Zelle eine Zusammenfassung („2 Spleisse · 1 Adresse“), „Löschen“ nimmt die Faser vom Port, und bei zusammengeführten Ports kommt „Trennen“ hinzu.</p><p><strong>Ports zusammenführen</strong></p><p>Auf eine Seite eines Ports gehört immer nur eine Faser. Wenn mehrere Fasern in einen gemeinsamen Anschluss laufen – etwa an einem Splitter –, führen Sie stattdessen die Ports zusammen:</p><ol><li>Klicken Sie auf das Zusammenführen-Symbol in der Spaltenüberschrift „Faser A“ oder „Faser B“. Die Tabelle wechselt in einen Auswahlmodus und zeigt vor jeder Zeile ein Kästchen.</li><li>Kreuzen Sie mindestens zwei <strong>aufeinanderfolgende</strong> Ports an. Das Kästchen in der Überschrift wählt alle auf einmal aus.</li><li>Klicken Sie unten rechts auf „Zusammenführen“; die Schaltfläche nennt die Zahl der ausgewählten Ports. Sie erscheint erst mit dem zweiten Kästchen, links davon steht die betroffene Seite („Seite: A (IN)“).</li></ol><p><img src="'+A+'" alt="Screenshot des maximierten Fensters „Netzknotenstruktur“ mit der Tabelle der Ports im Auswahlmodus zum Zusammenführen von Ports" class="big" data-zoomable="true"></p><p>Die zusammengeführten Ports stehen danach als eine Zelle mit dem Bereich („1-3“) und teilen sich eine Faser. „Trennen“ löst die Gruppe wieder auf. Das Symbol in der Spaltenüberschrift beendet den Auswahlmodus, ohne etwas zusammenzuführen.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Zusammenführen geht nur auf einer Seite und nur bei lückenlos aufeinanderfolgenden Ports. Andernfalls meldet Qonnectra „Ports von verschiedenen Seiten können nicht zusammengeführt werden“ beziehungsweise – englisch – „Ports must be consecutive (e.g., 1-2-3, not 1-3)“. Auch andere Meldungen dieser Tabelle sind teils englisch, etwa „No available ports“, wenn ab der Zelle kein freier Port mehr folgt.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Auf eine zusammengeführte Gruppe gehört ebenfalls nur eine einzelne Faser: Ziehen Sie ein Bündel oder ein Kabel darauf, meldet Qonnectra „Nur einzelne Fasern können mit Ports verbunden werden“.</p></div><h2 id="_14-9-subnetz-eines-netzknotens" tabindex="-1">14.9 Subnetz eines Netzknotens <a class="header-anchor" href="#_14-9-subnetz-eines-netzknotens" aria-label="Permalink to &quot;14.9 Subnetz eines Netzknotens&quot;">​</a></h2><p>Netzknoten können einander untergeordnet sein, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-3-netzknoten-container-slots-komponenten-und-ports">Netzknoten, Container, Slots, Komponenten und Ports</a>. Das <strong>Subnetz</strong> ist das Schema dieser Unterordnung: Es zeigt einen Netzknoten mit den Netzknoten, die unter ihm hängen, und den Kabeln dazwischen.</p><p>Sie öffnen es im Reiter „Aktionen“ des übergeordneten Netzknotens mit „Subnetz öffnen“. Die Zeichenfläche verhält sich wie im Hauptschema, passt sich beim Öffnen aber selbst auf das Diagramm an. Im Bereich „Eigenschaften“ steht zusätzlich „Zurück zum Hauptschema“.</p><p><img src="'+N+'" alt="Screenshot des Subnetzes eines Verteilers mit dem Verteiler in der Mitte und den Hausanschlüssen ringsum" data-zoomable="true"></p><p>Das Subnetz ist der Ort für die Hausanschlusskabel: Ein Kabel, das Sie hier anlegen, gehört zu diesem Subnetz und erscheint im Hauptschema nicht. Umgekehrt fehlen die Kabel des Hauptschemas im Subnetz.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Subnetz öffnen“ steht nur an Netzknotentypen, die Ihre Administration in den Netzschema-Einstellungen dafür freigegeben hat, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>. An allen anderen Netzknoten fehlt die Schaltfläche, auch wenn untergeordnete Netzknoten vorhanden sind.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Position eines Netzknotens im Subnetz wird getrennt von der im Hauptschema gespeichert. Ein Netzknoten, der in beiden Diagrammen vorkommt, kann darin also an verschiedenen Stellen liegen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der übergeordnete Netzknoten steht im Feld „Übergeordneter Netzknoten“ im Reiter „Eigenschaften“. Solange am untergeordneten Netzknoten Kabel hängen, ist das Feld im Subnetz gesperrt („Der übergeordnete Netzknoten kann nicht geändert werden, da dieser Netzknoten verbundene Kabel hat.“).</p></div><h2 id="_14-10-anzeigeoptionen-einrasten-kabelrichtungs-animation" tabindex="-1">14.10 Anzeigeoptionen: Einrasten, Kabelrichtungs-Animation <a class="header-anchor" href="#_14-10-anzeigeoptionen-einrasten-kabelrichtungs-animation" aria-label="Permalink to &quot;14.10 Anzeigeoptionen: Einrasten, Kabelrichtungs-Animation&quot;">​</a></h2><p>Die beiden Umschalter unter „Anzeigeoptionen“ im Bereich „Eigenschaften“ betreffen nur die Darstellung; gespeichert werden sie in Ihrem Browser, nicht am Projekt.</p><ul><li><strong>„Einrasten“</strong> (voreingestellt eingeschaltet) lässt die Scheitelpunkte einer Kabellinie auf ein Raster von 20 Pixeln springen, siehe Abschnitt <a href="#_14-4-1-verlauf-eines-kabels-andern">Verlauf eines Kabels ändern</a>. Ausgeschaltet folgen sie der Maus frei.</li><li><strong>„Kabelrichtungs-Animation“</strong> (voreingestellt ausgeschaltet) lässt weiße Striche auf allen Kabeln vom Anfangs- zum Endknoten wandern. So sehen Sie auf einen Blick, welches Ende eines Kabels als Anfang eingetragen ist.</li></ul><p>Die Farbe der Kabellinien stellen Sie nicht hier, sondern in den Einstellungen unter „Kabelfarbe“ ein, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>.</p><h2 id="_14-11-kartenkoordinaten-mit-dem-schema-synchronisieren" tabindex="-1">14.11 Kartenkoordinaten mit dem Schema synchronisieren <a class="header-anchor" href="#_14-11-kartenkoordinaten-mit-dem-schema-synchronisieren" aria-label="Permalink to &quot;14.11 Kartenkoordinaten mit dem Schema synchronisieren&quot;">​</a></h2><p>Ein Netzknoten hat zwei Positionen: die geografische aus der Karte und die auf der Zeichenfläche. Beim Öffnen des Netzschemas prüft Qonnectra, ob Netzknoten ohne Position auf der Zeichenfläche vorhanden sind, und rechnet sie aus den Kartenkoordinaten aus. Ist das geschehen, meldet es „Canvas Synchronisierung erfolgreich“.</p><p>Diese Synchronisierung läuft nur in eine Richtung und nur einmal je Netzknoten:</p><ul><li>Ein neu hinzugekommener Netzknoten steht beim nächsten Öffnen an der Stelle, die seiner Lage im Gelände entspricht – maßstäblich verkleinert und auf das Raster gerundet.</li><li>Sobald er eine Position hat, bleibt sie, wo sie ist. Verschieben Sie ihn in der Zeichenfläche, ändert das die Karte nicht; verschieben Sie ihn in QGIS, ändert das das Schema nicht.</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Arbeiten mehrere Personen gleichzeitig, führt Qonnectra die Synchronisierung nur einmal aus: Läuft sie bereits, wartet die Ansicht bis zu 30 Sekunden auf das Ergebnis.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Schlägt die Synchronisierung fehl, meldet Qonnectra „Fehler beim Synchronisieren der Canvas“. Das Schema öffnet trotzdem, greift für die betroffenen Netzknoten aber auf eine grobe Notrechnung zurück: Sie liegen dann alle dicht beieinander und müssen von Hand auseinandergezogen werden.</p></div>',30)])])}const Q=s(F,[["render",P]]);export{T as __pageData,Q as default};
